import React, { useEffect, useRef, useState, useCallback } from "react";
import { MapContainer, TileLayer, Popup, CircleMarker, Polyline } from "react-leaflet";
import L from "leaflet";
import { Box, Typography, Chip, CircularProgress } from "@mui/material";
import "leaflet/dist/leaflet.css";

// Fix marker icons (works in CRA/Vite; adjust if using Next/ESM-only)
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png"),
  iconUrl: require("leaflet/dist/images/marker-icon.png"),
  shadowUrl: require("leaflet/dist/images/marker-shadow.png"),
});

const MapVisualization = ({ stressData = [], ratingsData, loading }) => {
  const mapRef = useRef(null);
  const [busData, setBusData] = useState(null);

  // Load bus data from GeoJSON
  useEffect(() => {
    const loadBusData = async () => {
      try {
        const response = await fetch("/data/oneline_buses.geojson");
        const geojson = await response.json();
        setBusData(geojson);
      } catch (error) {
        console.error("Error loading bus data:", error);
      }
    };

    loadBusData();
  }, []);

  const defaultCenter = [21.35, -157.82];

  const getBusCoordinates = (busId) => {
    if (!busData) return [21.33 + (busId % 10) * 0.003, -157.9 + (busId % 8) * 0.003];

    // Find the bus in the GeoJSON data
    const busFeature = busData.features.find((feature) => feature.properties.BusNum === busId);
    if (busFeature) {
      const [lng, lat] = busFeature.geometry.coordinates;
      return [lat, lng]; // Convert to [lat, lng] for Leaflet
    }

    // Fallback
    return [21.33 + (busId % 10) * 0.003, -157.9 + (busId % 8) * 0.003];
  };

  const getBusInfo = (busId) => {
    if (!busData) return { name: `Bus ${busId}`, voltage: "Unknown" };

    const busFeature = busData.features.find((feature) => feature.properties.BusNum === busId);
    if (busFeature) {
      return {
        name: busFeature.properties.BusName,
        voltage: busFeature.properties.kV,
      };
    }

    return { name: `Bus ${busId}`, voltage: "Unknown" };
  };

  const getUtilizationColor = useCallback((u) => {
    const utilization = Number.isFinite(u) ? Math.max(0, Math.min(100, u)) : 0;

    // Create a smooth color gradient from green (0%) to red (100%)
    if (utilization <= 50) {
      // Green to yellow gradient (0% to 50%)
      const ratio = utilization / 50;
      const r = Math.round(76 + (255 - 76) * ratio); // 76 to 255
      const g = Math.round(175 + (193 - 175) * ratio); // 175 to 193
      const b = Math.round(80 + (7 - 80) * ratio); // 80 to 7
      return `rgb(${r}, ${g}, ${b})`;
    } else {
      // Yellow to red gradient (50% to 100%)
      const ratio = (utilization - 50) / 50;
      const r = Math.round(255 + (244 - 255) * ratio); // 255 to 244
      const g = Math.round(193 + (67 - 193) * ratio); // 193 to 67
      const b = Math.round(7 + (54 - 7) * ratio); // 7 to 54
      return `rgb(${r}, ${g}, ${b})`;
    }
  }, []);

  const getLineWeight = useCallback((u) => {
    // Use consistent thickness for all lines regardless of utilization
    return 6;
  }, []);

  const createTransmissionLines = () =>
    (stressData || []).map((line) => {
      const bus0Coords = getBusCoordinates(line.bus0);
      const bus1Coords = getBusCoordinates(line.bus1);
      const utilization = line?.utilization_pct ?? 0;
      const color = getUtilizationColor(utilization);
      const weight = getLineWeight(utilization);

      // Create a unique key that includes utilization to force re-render when data changes
      const uniqueKey = `${line.line_id}-${utilization.toFixed(1)}`;

      return (
        <Polyline
          key={uniqueKey}
          positions={[bus0Coords, bus1Coords]}
          color={color}
          weight={weight}
          opacity={0.9}
          // Canvas + Huawei tend to like these:
          pane="overlayPane"
          bubblingMouseEvents={false}
        >
          <Popup>
            <Box sx={{ minWidth: 200 }}>
              <Typography variant="h6" gutterBottom>
                Line: {line.line_id}
              </Typography>
              <Typography variant="body2" gutterBottom>
                <strong>From:</strong> {line.bus0_name} (Bus {line.bus0})
                <br />
                <strong>To:</strong> {line.bus1_name} (Bus {line.bus1})
                <br />
                <strong>Conductor:</strong> {line.conductor}
                <br />
                <strong>Voltage:</strong> {line.voltage_kv} kV
                <br />
                <strong>MOT:</strong> {line.mot_c}°C
              </Typography>
              <Box sx={{ mt: 1 }}>
                <Chip
                  label={`${(line.utilization_pct ?? 0).toFixed(1)}% Utilization`}
                  color={(line.utilization_pct ?? 0) >= 100 ? "error" : (line.utilization_pct ?? 0) >= 80 ? "warning" : "success"}
                  size="small"
                />
              </Box>
              <Typography variant="body2" sx={{ mt: 1 }}>
                <strong>Rating:</strong> {(line.rating_amps ?? 0).toFixed(0)} A ({(line.rating_mva ?? 0).toFixed(1)} MVA)
                <br />
                <strong>Flow:</strong> {(line.flow_amps ?? 0).toFixed(0)} A ({(line.flow_mva ?? 0).toFixed(1)} MVA)
                <br />
                <strong>Margin:</strong> {((line.rating_amps ?? 0) - (line.flow_amps ?? 0)).toFixed(0)} A
              </Typography>
            </Box>
          </Popup>
        </Polyline>
      );
    });

  const createBusMarkers = () => {
    const uniqueBuses = new Set();
    (stressData || []).forEach((l) => {
      uniqueBuses.add(l.bus0);
      uniqueBuses.add(l.bus1);
    });

    return Array.from(uniqueBuses).map((busId) => {
      const coords = getBusCoordinates(busId);
      const busInfo = getBusInfo(busId);
      const voltage = busInfo.voltage;

      const size = voltage >= 138 ? 12 : voltage >= 69 ? 10 : 8;
      const color = "#1976d2"; // All buses use the same blue color

      return (
        <CircleMarker key={`bus-${busId}`} center={coords} radius={size} color={color} fillColor={color} fillOpacity={0.85} weight={2}>
          <Popup>
            <Box sx={{ minWidth: 150 }}>
              <Typography variant="h6" gutterBottom>
                {busInfo.name}
              </Typography>
              <Typography variant="body2">
                <strong>Bus ID:</strong> {busId}
                <br />
                <strong>Voltage:</strong> {voltage} kV
                <br />
                <strong>Coordinates:</strong> {coords[0].toFixed(4)}, {coords[1].toFixed(4)}
              </Typography>
            </Box>
          </Popup>
        </CircleMarker>
      );
    });
  };

  // Update map when stressData changes
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !stressData?.length) return;

    // Log color updates for debugging
    console.log("Map data updated, recalculating colors...");
    stressData.forEach((line) => {
      const utilization = line?.utilization_pct ?? 0;
      const color = getUtilizationColor(utilization);
      console.log(`Line ${line.line_id}: ${utilization.toFixed(1)}% utilization -> ${color}`);
    });

    const allCoords = [];
    stressData.forEach((line) => {
      allCoords.push(getBusCoordinates(line.bus0));
      allCoords.push(getBusCoordinates(line.bus1));
    });
    if (allCoords.length) {
      const bounds = L.latLngBounds(allCoords).pad(0.1);
      map.fitBounds(bounds, { padding: [30, 30] });
    }

    map.invalidateSize(); // important on mobile WebView
  }, [stressData]);

  // Force map re-render when data changes
  useEffect(() => {
    const map = mapRef.current;
    if (map && stressData?.length) {
      // Small delay to ensure all updates are processed
      setTimeout(() => {
        map.invalidateSize();
        map.redraw();
      }, 100);
    }
  }, [stressData]);

  return (
    <Box sx={{ height: "500px", position: "relative" }}>
      <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 1 }}>
        <Typography variant="h6">Grid Line Status Map</Typography>
        {stressData?.length > 0 && <Chip label={`${stressData.length} lines`} size="small" color="primary" variant="outlined" />}
      </Box>

      {loading && (
        <Box
          sx={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            zIndex: 1000,
            backgroundColor: "rgba(255, 255, 255, 0.8)",
            borderRadius: 1,
            p: 2,
          }}
        >
          <CircularProgress />
          <Typography variant="body2" sx={{ mt: 1 }}>
            Loading data...
          </Typography>
        </Box>
      )}

      <MapContainer
        whenCreated={(map) => {
          mapRef.current = map;
          // small delay helps Huawei WebView settle layout
          setTimeout(() => map.invalidateSize(), 50);
        }}
        preferCanvas={true} // <-- key for Huawei devices
        center={defaultCenter}
        zoom={10}
        style={{ height: "100%", width: "100%" }}
        // remove "bounds" and "boundsOptions" to avoid conflicts
        // smooth updates on mobile
        updateWhenIdle={false}
      >
        <TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        {createTransmissionLines()}
        {createBusMarkers()}
      </MapContainer>

      {/* Legend */}
      <Box sx={{ mt: 2 }}>
        <Typography variant="body2" gutterBottom>
          <strong>Legend:</strong>
        </Typography>
        <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap", alignItems: "center", mb: 1 }}>
          <Typography variant="body2" sx={{ mr: 1 }}>
            <strong>Transmission Lines:</strong>
          </Typography>
          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
            <div style={{ width: 20, height: 4, backgroundColor: "#4caf50", borderRadius: 2 }} />
            <Typography variant="body2">0%</Typography>
          </Box>
          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
            <div style={{ width: 20, height: 4, backgroundColor: "#ffc107", borderRadius: 2 }} />
            <Typography variant="body2">50%</Typography>
          </Box>
          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
            <div style={{ width: 20, height: 4, backgroundColor: "#f44336", borderRadius: 2 }} />
            <Typography variant="body2">100%</Typography>
          </Box>
          <Typography variant="body2" sx={{ ml: 2 }}>
            Color gradient shows utilization percentage (thickness is consistent)
          </Typography>
        </Box>
        <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap", alignItems: "center" }}>
          <Typography variant="body2" sx={{ mr: 1 }}>
            <strong>Bus/Substations:</strong>
          </Typography>
          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
            <div style={{ width: 12, height: 12, borderRadius: "50%", backgroundColor: "#d32f2f" }} />
            <Typography variant="body2">138kV+</Typography>
          </Box>
          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5, ml: 1 }}>
            <div style={{ width: 10, height: 10, borderRadius: "50%", backgroundColor: "#1976d2" }} />
            <Typography variant="body2">69kV</Typography>
          </Box>
          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5, ml: 1 }}>
            <div style={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: "#388e3c" }} />
            <Typography variant="body2">Lower</Typography>
          </Box>
        </Box>
      </Box>
    </Box>
  );
};

export { MapVisualization };
